window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d43efec5b759f492"]={"versions": [{"id": "FIG-d43efec5b759f492", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des AUTOSAR-ECU-Konfigurationsmetamodells (ECUC Parameter Configuration Container Definition) für das BSW-Modul Data Distribution Service (DDS) innerhalb der AUTOSAR Classic Platform. Es spezifiziert die strukturelle Zusammensetzung und Kardinalitäten der Konfigurationscontainer, Parameter und Referenzen zur Konfiguration eines DDS-Topics.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentraler Container ist <code>DdsTopic</code> vom Typ <code>EcucParamConfContainerDef</code> (Multiplizität 0..65535). Über Kompositionsbeziehungen aggregiert <code>DdsTopic</code>:</p>\n<ul class=\"fig-list\"><li><code>DdsTopicName</code> (<code>+parameter</code>): Typ <code>EcucStringParamDef</code>, Multiplizität 1..1.\n</li><li><code>DdsTopicImplementationType</code> (<code>+reference</code>): Typ <code>EcucForeignReferenceDef</code>, Multiplizität 0..1, mit <code>destinationType = IMPLEMENTATION-DATA-TYPE</code>. Verweist über eine gerichtete gestrichelte Abhängigkeit auf <code>AbstractImplementationDataType / ImplementationDataType</code>.\n</li><li><code>DdsTopicQoS</code> (<code>+subContainer</code>): Sub-Container vom Typ <code>EcucParamConfContainerDef</code>, Multiplizität 1..1.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm der ECU-Konfiguration beschreibt das Schaubild keinen dynamischen Laufzeit- oder Sequenzablauf. Es legt die deklarative Struktur und Validierungsregeln fest, die im Konfigurations- und Generierungsprozess (ECUC-Toolchain) vor der Kompilierung ausgewertet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für die Parametrierung des DDS-Stacks:</p>\n<ul class=\"fig-list\"><li>Jedes definierte <code>DdsTopic</code> muss zwingend genau einen Topic-Namen (<code>DdsTopicName</code>) besitzen.\n</li><li>Die Zuordnung eines Implementierungsdatentyps (<code>DdsTopicImplementationType</code>) ist optional (0..1), bindet jedoch bei Vorhandensein an einen AUTOSAR <code>ImplementationDataType</code>.\n</li><li>Der Sub-Container <code>DdsTopicQoS</code> ist obligatorisch (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>), sodass für jedes Topic explizite Quality-of-Service-Parameter im Modell konfiguriert werden müssen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-be51615c2f21998c", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des AUTOSAR-ECU-Konfigurationsmetamodells (ECUC Parameter Configuration Container Definition) für das BSW-Modul Data Distribution Service (DDS) innerhalb der AUTOSAR Classic Platform. Es spezifiziert die strukturelle Zusammensetzung und Kardinalitäten der Konfigurationscontainer, Parameter und Referenzen zur Konfiguration eines DDS-Topics.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentraler Container ist <code>DdsTopic</code> vom Typ <code>EcucParamConfContainerDef</code> (Multiplizität 0..65535). Über Kompositionsbeziehungen aggregiert <code>DdsTopic</code>:</p>\n<ul class=\"fig-list\"><li><code>DdsTopicName</code> (<code>+parameter</code>): Typ <code>EcucStringParamDef</code>, Multiplizität 1..1.\n</li><li><code>DdsTopicImplementationType</code> (<code>+reference</code>): Typ <code>EcucForeignReferenceDef</code>, Multiplizität 0..1, mit <code>destinationType = IMPLEMENTATION-DATA-TYPE</code>. Verweist über eine gerichtete gestrichelte Abhängigkeit auf <code>AbstractImplementationDataType / ImplementationDataType</code>.\n</li><li><code>DdsTopicQoS</code> (<code>+subContainer</code>): Sub-Container vom Typ <code>EcucParamConfContainerDef</code>, Multiplizität 0..1.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm der ECU-Konfiguration beschreibt das Schaubild keinen dynamischen Laufzeit- oder Sequenzablauf. Es legt die deklarative Struktur und Validierungsregeln fest, die im Konfigurations- und Generierungsprozess (ECUC-Toolchain) vor der Kompilierung ausgewertet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für die Parametrierung des DDS-Stacks:</p>\n<ul class=\"fig-list\"><li>Jedes definierte <code>DdsTopic</code> muss zwingend genau einen Topic-Namen (<code>DdsTopicName</code>) besitzen.\n</li><li>Die Zuordnung eines Implementierungsdatentyps (<code>DdsTopicImplementationType</code>) ist optional (0..1), bindet jedoch bei Vorhandensein an einen AUTOSAR <code>ImplementationDataType</code>.\n</li><li>Der Sub-Container <code>DdsTopicQoS</code> ist optional (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>); wird kein QoS-Subcontainer angegeben, kommen systemspezifische Default-QoS-Parameter zur Anwendung.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-6adf25b1a4608031", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des AUTOSAR-ECU-Konfigurationsmetamodells (ECUC Parameter Configuration Container Definition) für das BSW-Modul Data Distribution Service (DDS) innerhalb der AUTOSAR Classic Platform. Es spezifiziert die strukturelle Zusammensetzung und Kardinalitäten der Konfigurationscontainer, Parameter und Referenzen zur Konfiguration eines DDS-Topics.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentraler Container ist <code>DdsTopic</code> vom Typ <code>EcucParamConfContainerDef</code> (Multiplizität 0..65535). Über Kompositionsbeziehungen aggregiert <code>DdsTopic</code>:</p>\n<ul class=\"fig-list\"><li><code>DdsTopicName</code> (<code>+parameter</code>): Typ <code>EcucStringParamDef</code>, Multiplizität 1..1.\n</li><li><code>DdsTopicImplementationType</code> (<code>+reference</code>): Typ <code>EcucForeignReferenceDef</code>, Multiplizität 0..1, mit <code>destinationType = IMPLEMENTATION-DATA-TYPE</code>. Verweist über eine gerichtete gestrichelte Abhängigkeit auf <code>AbstractImplementationDataType / ImplementationDataType</code>.\n</li><li><code>DdsTopicQoS</code> (<code>+subContainer</code>): Sub-Container vom Typ <code>EcucParamConfContainerDef</code>, Multiplizität 0..1.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm der ECU-Konfiguration beschreibt das Schaubild keinen dynamischen Laufzeit- oder Sequenzablauf. Es legt die deklarative Struktur und Validierungsregeln fest, die im Konfigurations- und Generierungsprozess (ECUC-Toolchain) vor der Kompilierung ausgewertet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für die Parametrierung des DDS-Stacks:</p>\n<ul class=\"fig-list\"><li>Jedes definierte <code>DdsTopic</code> muss zwingend genau einen Topic-Namen (<code>DdsTopicName</code>) besitzen.\n</li><li>Die Zuordnung eines Implementierungsdatentyps (<code>DdsTopicImplementationType</code>) ist optional (0..1), bindet jedoch bei Vorhandensein an einen AUTOSAR <code>ImplementationDataType</code>.\n</li><li>Der Sub-Container <code>DdsTopicQoS</code> ist optional (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>); wird kein QoS-Subcontainer angegeben, kommen systemspezifische Default-QoS-Parameter zur Anwendung.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-d43efec5b759f492", "to": "FIG-be51615c2f21998c", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Container <code>DdsTopicQoS</code>: <code>lowerMultiplicity</code> von <code>1</code> auf <code>0</code> geändert (Container ist nun optional statt verpflichtend).\n</li></ul>"}, {"from": "FIG-be51615c2f21998c", "to": "FIG-6adf25b1a4608031", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
